def _normalizar(valor):
    normalizado = unicodedata.normalize('NFKD', valor or '')
    ascii_texto = normalizado.encode('ascii', 'ignore').decode('ascii')
    return re.sub(r'[^a-z0-9]+', '', ascii_texto.casefold())


def separar_correos_existentes(apps, schema_editor):
    Usuario = apps.get_model('usuarios', 'Usuario')
    db_alias = schema_editor.connection.alias
    usuarios = Usuario.objects.using(db_alias).filter(
        models.Q(is_superuser=True)
        | models.Q(rol__nombre__iexact='Admin')
        | models.Q(rol__nombre__iexact='Colaborador')
    ).order_by('pk')

    for usuario in usuarios.iterator():
        correo_personal = usuario.correo_contacto or usuario.email
        nombre = _normalizar((usuario.nombre or '').strip().split(' ')[0])
        apellido_paterno = _normalizar((usuario.apellido_paterno or '').strip().split(' ')[0])
        apellido_materno = _normalizar((usuario.apellido_materno or '').strip())
        base = (
            f'{nombre[0]}{apellido_paterno[0]}.{apellido_materno}'
            if nombre and apellido_paterno and apellido_materno
            else _normalizar(usuario.email.split('@', 1)[0])
        )
        numero = 1
        while True:
            sufijo = '' if numero == 1 else str(numero)
            acceso = f'{base}{sufijo}@nicolettstudio.cl'
            duplicado = Usuario.objects.using(db_alias).filter(
                email__iexact=acceso,
            ).exclude(pk=usuario.pk).exists()
            if not duplicado:
                break
            numero += 1

        usuario.correo_contacto = correo_personal
        usuario.email = acceso
        campos_actualizados = ['correo_contacto', 'email']
        if usuario.rol.nombre.casefold() == 'colaborador':
            usuario.is_staff = False
            campos_actualizados.append('is_staff')
        usuario.save(using=db_alias, update_fields=campos_actualizados)


def restaurar_correos_existentes(apps, schema_editor):
    Usuario = apps.get_model('usuarios', 'Usuario')
    db_alias = schema_editor.connection.alias
    usuarios = Usuario.objects.using(db_alias).filter(
        models.Q(is_superuser=True)
        | models.Q(rol__nombre__iexact='Admin')
        | models.Q(rol__nombre__iexact='Colaborador')
    ).order_by('pk')
    for usuario in usuarios.iterator():
        campos_actualizados = ['correo_contacto']
        if usuario.correo_contacto:
            usuario.email = usuario.correo_contacto
            campos_actualizados.append('email')
        usuario.correo_contacto = ''
        if usuario.rol.nombre.casefold() == 'colaborador':
            usuario.is_staff = True
            campos_actualizados.append('is_staff')
        usuario.save(using=db_alias, update_fields=campos_actualizados)


